      .eq("email", normalizedEmail)
      .is("verified_at", null)
      .order("created_at", { ascending: false })
      .limit(1)
      .single();

    if (data?.code) {
      return data.code as string;
    }
  }

  throw new Error(`No verification code found for ${email} after 20s`);
}

