export async function createParticipant(opts: {
  email: string;
  name: string;
  lookingForTeam?: boolean;
}) {
  const admin = getAdminClient();

  // Check if auth user already exists (paginated - default is 50, we need to search properly)
  const existing = await findAuthUserByEmail(admin, opts.email);

  let userId: string;
  if (existing) {
    userId = existing.id;
    // Update password in case it changed
    await admin.auth.admin.updateUserById(userId, {
      password: TEST_PASSWORD,
      email_confirm: true,
    });
  } else {
    const { data, error } = await admin.auth.admin.createUser({
      email: opts.email,
      password: TEST_PASSWORD,
      email_confirm: true,
      user_metadata: { name: opts.name },
    });
    if (error) throw new Error(`Failed to create participant ${opts.email}: ${error.message}`);
    userId = data.user.id;
  }

  await admin.from("profiles").upsert({
    id: userId,
    email: opts.email,
    name: opts.name,
    role: "participant",
    looking_for_team: opts.lookingForTeam ?? false,
  });

  return userId;
}

/**
 * Create a participant the way bulk imports do: auth user WITHOUT a
 * password + profile. These users can only get access via the password
 * recovery flow. Returns the user ID.
 * Idempotent: deletes any existing user with this email first so the
 * "no password" state is guaranteed.
 */
export async function createApplication(opts: {
  chapterId: string;
  email: string;
  firstName: string;
  lastName: string;
  status: "pending" | "accepted" | "rejected" | "waitlisted" | "checked_in" | "cancelled";
  existingTeamId?: string | null;
}) {
  const admin = getAdminClient();
  const { data, error } = await admin
    .from("applications")
    .upsert(
      {
        chapter_id: opts.chapterId,
        email: opts.email,
        first_name: opts.firstName,
        last_name: opts.lastName,
        status: opts.status,
        existing_team_id: opts.existingTeamId ?? null,
        form_data: {},
        consent_attendance: true,
        consent_privacy: true,
      },
      { onConflict: "chapter_id,email" }
    )
    .select("id")
    .single();

  if (error) throw new Error(`Failed to create application for ${opts.email}: ${error.message}`);
  return data.id as string;
}

